    R, C = len(grid), len(grid[0])
    markers = []
    for r in range(1, R-1):
        for c in range(1, C-1):
            if grid[r][c] != 2:
                continue
            if all(grid[r+dr][c+dc] == (2 if dr == 0 and dc == 0 else 3)
                   for dr in (-1, 0, 1) for dc in (-1, 0, 1)):
                markers.append((r, c))
    for r, c in markers:
        horiz = sum(grid[r][x] == 2 for x in range(C) if x not in range(c-1,c+2))
        vert = sum(grid[y][c] == 2 for y in range(R) if y not in range(r-1,r+2))
        # The marker lies on a long 2-line; extend perpendicular to it.
        support_horizontal = horiz >= vert
        if support_horizontal:
            # Find the nearest parallel 2-line beyond the marker, then continue to the edge.
            candidates = [y for y in range(R) if y != r and sum(grid[y][x] == 2 for x in range(C)) >= C-1]
            if not candidates:
                continue
            t = min(candidates, key=lambda y: abs(y-r))
            step = 1 if t > r else -1
            for y in range(r+step, (R if step > 0 else -1), step):
                out[y][c] = 1
            # Widen the trail around the crossing line, leaving its center 2 intact.
            for y in (t-step, t+step):
                if 0 <= y < R:
                    for x in (c-1, c, c+1):
                        if 0 <= x < C: out[y][x] = 1
            for x in (c-1, c+1):
                if 0 <= x < C: out[t][x] = 1
        else:
            candidates = [x for x in range(C) if x != c and sum(grid[y][x] == 2 for y in range(R)) >= R-1]
            if not candidates:
